/** 
 * Calls  {@link Context#startForegroundService(Intent)} if {@link #SDK_INT} is 26 or higher, or{@link Context#startService(Intent)} otherwise.
 * @param context The context to call.
 * @param intent The intent to pass to the called method.
 * @return The result of the called method.
 */
@Nullable public static ComponentName startForegroundService(Context context,Intent intent){
  if (Util.SDK_INT >= 26) {
    return context.startForegroundService(intent);
  }
 else {
    return context.startService(intent);
  }
}
